import * as THREE from '../lib/three.module.min.js'
import { GLTFLoader } from '../lib/GLTFLoader.min.js'

// The superpower models. They're generated by tools/make_ability_models.py;
// the node names used below (FlameOuter, ShieldRingA, Exhaust...) come from
// that script, so rename in both places or neither.
const MODEL_DIR = './assets/models/abilities/'
const MODEL_FILES = {
  oilslick: 'oilslick.glb',
  shockwave: 'shockwave.glb',
  boost: 'boost.glb',
  homingshot: 'homingshot.glb',
  shield: 'shield.glb',
  itembox: 'itembox.glb',
}

const templates = {} // id -> THREE.Group, only for models that loaded
let loadPromise = null

/** glTF PBR -> the game's flat-shaded Lambert look (same as the cars). */
function toLambert(src) {
  return new THREE.MeshLambertMaterial({
    name: src.name,
    color: src.color,
    emissive: src.emissive,
    transparent: src.transparent,
    opacity: src.opacity,
    side: src.side,
    depthWrite: src.depthWrite,
    flatShading: true,
  })
}

/** Fetch every ability model once. Never rejects: a model that fails to load
 * is simply absent, and callers fall back to their old primitive shapes. */
export function loadAbilityModels() {
  if (loadPromise) return loadPromise
  const loader = new GLTFLoader()
  loadPromise = Promise.all(Object.entries(MODEL_FILES).map(([id, file]) =>
    loader.loadAsync(MODEL_DIR + file)
      .then((gltf) => {
        gltf.scene.traverse((o) => { if (o.isMesh) o.material = toLambert(o.material) })
        templates[id] = gltf.scene
      })
      .catch((e) => console.warn(`Ability model "${id}" failed to load, using a plain shape instead:`, e))
  )).then(() => Object.keys(templates).length)
  return loadPromise
}

/** A fresh copy of a model, or null if it isn't loaded. `ownMaterials` gives
 * the copy private materials, needed whenever you fade or recolour it. */
export function cloneAbilityModel(id, { ownMaterials = false } = {}) {
  const template = templates[id]
  if (!template) return null
  const copy = template.clone(true)
  if (ownMaterials) copy.traverse((o) => { if (o.isMesh) o.material = o.material.clone() })
  return copy
}

/** Every material under `root`, with its starting opacity, for fade-outs. */
export function collectFadeables(root) {
  const out = []
  root.traverse((o) => {
    if (!o.isMesh) return
    out.push({ material: o.material, base: o.material.opacity })
  })
  return out
}

export function setFade(fadeables, factor) {
  for (const f of fadeables) {
    f.material.transparent = true
    f.material.opacity = f.base * factor
  }
}

// ---------------------------------------------------------------- shield

/** The bubble around a shielded car. update() is called every frame. */
export function createShieldVisual() {
  const root = new THREE.Group()
  root.position.y = 0.9
  root.scale.setScalar(1.7)
  root.visible = false

  const model = cloneAbilityModel('shield')
  let rings = []
  if (model) {
    root.add(model)
    rings = ['ShieldRingA', 'ShieldRingB', 'ShieldRingC'].map((n) => model.getObjectByName(n)).filter(Boolean)
  } else {
    // fallback: the original plain translucent sphere
    root.add(new THREE.Mesh(
      new THREE.SphereGeometry(1, 12, 8),
      new THREE.MeshBasicMaterial({ color: 0x7ec8e3, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false })
    ))
  }

  let t = 0
  return {
    object: root,
    /** remainingMs <= 0 hides it; the last 900ms blink as a "wearing off" warning. */
    update(dt, remainingMs) {
      if (remainingMs <= 0) { root.visible = false; return }
      t += dt
      const blinkOff = remainingMs < 900 && Math.floor(t * 12) % 2 === 0
      root.visible = !blinkOff
      rings.forEach((r, i) => { r.rotation.y += dt * (0.9 + i * 0.7) * (i % 2 ? -1 : 1) })
      const pulse = 1 + Math.sin(t * 4) * 0.025
      root.scale.setScalar(1.7 * pulse)
    },
  }
}

// ----------------------------------------------------------------- boost

/** Twin exhaust flames mounted at the back of a car's body. */
export function createBoostFlames(dims) {
  const root = new THREE.Group()
  root.visible = false
  const flames = []

  const sideX = dims.exhaustX ?? 0.4
  for (const side of [-1, 1]) {
    const model = cloneAbilityModel('boost')
    if (!model) continue
    model.position.set(side * sideX, dims.exhaustY ?? 0.34, dims.rearZ ?? -1.3)
    root.add(model)
    flames.push({
      layers: ['FlameOuter', 'FlameMid', 'FlameCore'].map((n) => model.getObjectByName(n)).filter(Boolean),
      phase: side * 1.7,
    })
  }

  let t = 0
  return {
    object: root,
    update(dt, active) {
      root.visible = active && flames.length > 0
      if (!root.visible) return
      t += dt
      for (const f of flames) {
        f.layers.forEach((layer, i) => {
          const wobble = Math.sin(t * (38 + i * 9) + f.phase + i)
          layer.scale.set(1 + wobble * 0.08, 1 + wobble * 0.08, 1 + wobble * 0.22)
        })
      }
    },
  }
}
